window.R37_LINES = ["Claude, aplikasi buatanku harus ngebut, pelangganku nggak sabar nunggu.", "Kerjakan dua puluh empat perbaikan ini.", "Pasang skeleton loading, biar layar nggak pernah kosong.", "Tampilan berubah duluan, server menyusul kemudian.", "Jawaban AI muncul kata demi kata, nggak nunggu selesai.", "Daftar panjang divirtualisasi, cuma yang kelihatan yang digambar.", "Gambar pakai WebP atau AVIF, file-nya lebih kecil.", "Gambar di bawah layar dimuat belakangan.", "JavaScript dipecah per halaman, yang dimuat cuma yang perlu.", "Script pihak ketiga dimuat setelah halaman siap.", "Buang library yang nggak dipakai.", "Taruh file di CDN, dikirim dari lokasi terdekat.", "Aktifkan kompresi Gzip, kiriman jadi lebih ringan.", "Pakai cache browser, kunjungan berikutnya nggak unduh ulang.", "Pencarian pakai debounce, cari setelah orang berhenti ngetik.", "Cegah request dobel waktu tombol diklik dua kali.", "Request yang nggak saling tunggu, jalankan bareng.", "Kasih batas waktu ke layanan luar, biar nggak ikut macet.", "Tugas berat lempar ke antrean di belakang layar.", "Data yang sering dibuka, simpan sementara di Redis.", "Tambah index di database, pencarian nggak periksa semua baris.", "Benahi query N plus satu, ambil datanya sekaligus.", "Ambil kolom yang perlu aja, bukan semuanya.", "Hasil yang banyak dibagi per halaman, pakai pagination.", "Pakai connection pooling, koneksi database dipakai ulang.", "Terakhir, tes di HP murah dan sinyal lemah.", "Komen APP, aku kirim semua prompt-nya buat Claude lewat DM."];
